export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed ?? 4);
  const g = Number(inputs.gravity ?? 9.8);
  const m = Number(inputs.mass ?? 1);
  const tTop = u / g;
  const tEnd = 2 * u / g;
  const t = sdk.clamp(Number(time) || 0, 0, tEnd);
  let v = u - g * t;
  if (Math.abs(v) < 1e-9) v = 0;
  let h = u * t - g * t * t / 2;
  if (h < 0) h = 0;
  const a = -g;
  const F = m * g;
  const H = u * u / (2 * g);

  let state;
  let stateIdx;
  if (t <= 1e-9) { state = 'Ready to toss'; stateIdx = 0; }
  else if (Math.abs(t - tTop) < 1e-3) { state = 'At the top'; stateIdx = 2; }
  else if (t >= tEnd - 1e-9) { state = 'Back at launch height'; stateIdx = 4; }
  else if (t < tTop) { state = 'Rising'; stateIdx = 1; }
  else { state = 'Falling'; stateIdx = 3; }

  const objs = [];
  // Left scene: the motion
  objs.push(sdk.text('leftTitle', 20, 40, 'The motion', { role: 'neutral' }));
  objs.push(sdk.text('leftState', 20, 64, state, { role: 'output' }));
  const rBottom = 330, rLen = 230;
  const hy = sdk.linear([0, 2.2], [rBottom, rBottom - rLen]);
  objs.push(sdk.axis('ruler', { x: 72, y: rBottom, length: rLen, orientation: 'y', min: 0, max: 2.2, label: 'Height', unit: 'm' }));
  objs.push(...sdk.groundMark('launchMark', 140, rBottom, 60));
  const bx = 140;
  const by = hy(h) - 11;
  objs.push(sdk.circle('ball', bx, by, 22, { role: 'neutral' }));
  objs.push(...sdk.vector('velArrow', { x: bx - 4, y: by }, { value: Math.abs(v), direction: v >= 0 ? 'up' : 'down' }, { scale: 10, label: 'v', role: 'input' }));
  objs.push(...sdk.vector('accArrow', { x: bx + 16, y: by }, { value: g, direction: 'down' }, { scale: 4.5, label: 'a', role: 'warning' }));
  const cy = sdk.clamp(by - 40, 100, 290);
  objs.push(...sdk.callout(180, cy, [
    'v = ' + sdk.format(v, 2) + ' m/s',
    'a = ' + sdk.format(a, 1) + ' m/s²',
    'F = ' + sdk.format(F, 1) + ' N down'
  ], { id: 'info' }));

  // Right scene: velocity over time
  objs.push(sdk.text('rightTitle', 340, 40, 'Velocity over time', { role: 'neutral' }));
  objs.push(sdk.text('rightState', 340, 64, 'v = u − g t', { role: 'output' }));
  const gx = 392, gBottom = 360, gW = 230, gH = 250;
  const px = sdk.linear([0, 1.8], [gx, gx + gW]);
  const py = sdk.linear([-5.5, 5.5], [gBottom, gBottom - gH]);
  objs.push(sdk.axis('tAxis', { x: gx, y: gBottom, length: gW, orientation: 'x', min: 0, max: 1.8, label: 'Time', unit: 's' }));
  objs.push(sdk.axis('vAxis', { x: gx, y: gBottom, length: gH, orientation: 'y', min: -5.5, max: 5.5, label: 'Velocity', unit: 'm/s' }));
  objs.push(sdk.line('zeroLine', gx, py(0), gx + gW, py(0), { role: 'neutral', opacity: 0.35 }));
  const vf = (s) => u - g * s;
  objs.push(sdk.polyline('vFuture', [[px(t), py(vf(t))], [px(tEnd), py(vf(tEnd))]], { role: 'neutral', opacity: 0.3 }));
  if (t > 1e-6) {
    objs.push(sdk.polyline('vTrace', [[px(0), py(vf(0))], [px(t), py(vf(t))]], { role: 'input' }));
  }
  const s0 = Math.max(0, t - 0.15), s1 = Math.min(tEnd, t + 0.15);
  objs.push(sdk.line('slopeSeg', px(s0), py(vf(s0)), px(s1), py(vf(s1)), { role: 'warning' }));
  // Upper-right corner of the graph: the falling v-t line never reaches it for any allowed input.
  const lx = gx + 56;
  const ly = 128;
  objs.push(sdk.text('slopeLabel', lx, ly, 'slope a = ' + sdk.format(a, 1) + ' m/s²', { role: 'warning' }));
  objs.push(sdk.circle('vMarker', px(t), py(v), 11, { role: 'input' }));

  const quantities = {
    launchSpeed: u, gravity: g, mass: m,
    apexTime: tTop, apexHeight: H,
    height: h, velocity: v, acceleration: a, force: F,
    motionState: stateIdx
  };
  return {
    frame: {
      width: 640, height: 420, objects: objs,
      readouts: [
        { id: 'velocity', value: v },
        { id: 'acceleration', value: a },
        { id: 'force', value: F },
        { id: 'motionState', value: state }
      ]
    },
    quantities
  };
}
